PREFIX dbo: <http://dbpedia.org/ontology/>
PREFIX dbr: <http://dbpedia.org/resource/>
PREFIX rdfs: <http://www.w3.org/2000/01/rdf-schema#>

SELECT ?person ?personLabel ?birth ?death ?ageYears WHERE {
  VALUES ?person { dbr:Jean-Rodolphe_Perronet dbr:Gunnar_Wiklund }
  OPTIONAL { ?person dbo:birthDate ?birth . }
  OPTIONAL { ?person dbo:deathDate ?death . }
  FILTER(BOUND(?birth) && BOUND(?death))
  BIND( (YEAR(?death) - YEAR(?birth)) AS ?yearDiff )
  BIND( IF( (MONTH(?death) < MONTH(?birth)) || (MONTH(?death) = MONTH(?birth) && DAY(?death) < DAY(?birth)), 1, 0) AS ?subtract )
  BIND( (?yearDiff - ?subtract) AS ?ageYears )
  OPTIONAL { ?person rdfs:label ?personLabel FILTER(lang(?personLabel) = "en") }
}
ORDER BY DESC(?ageYears)

